	@Inject
	public WebTestDslGrammarAccess(GrammarProvider grammarProvider,
			TerminalsGrammarAccess gaTerminals) {
		this.grammar = internalFindGrammar(grammarProvider);
		this.gaTerminals = gaTerminals;
		this.pMain = new MainElements();
		this.pNamedElement = new NamedElementElements();
		this.pVariable = new VariableElements();
		this.eType = new TypeElements();
		this.pDeclaration = new DeclarationElements();
		this.pPage = new PageElements();
		this.pOperation = new OperationElements();
		this.pTestCase = new TestCaseElements();
		this.pTestCaseInstance = new TestCaseInstanceElements();
		this.pBlockStatement = new BlockStatementElements();
		this.pStatement = new StatementElements();
		this.pVariableStatement = new VariableStatementElements();
		this.pIfStatement = new IfStatementElements();
		this.pWhileStatement = new WhileStatementElements();
		this.pCallStatement = new CallStatementElements();
		this.pOpenStatement = new OpenStatementElements();
		this.pElementStatement = new ElementStatementElements();
		this.pFillStatement = new FillStatementElements();
		this.pClickStatement = new ClickStatementElements();
		this.pContextStatement = new ContextStatementElements();
		this.pPrintStatement = new PrintStatementElements();
		this.pAssertStatement = new AssertStatementElements();
		this.pWaitStatement = new WaitStatementElements();
		this.pForEachStatement = new ForEachStatementElements();
		this.pIteratorVariable = new IteratorVariableElements();
		this.pExpression = new ExpressionElements();
		this.pNotExpression = new NotExpressionElements();
		this.pConditionalExpression = new ConditionalExpressionElements();
		this.pIsExpression = new IsExpressionElements();
		this.pContainsExpression = new ContainsExpressionElements();
		this.pExistsExpression = new ExistsExpressionElements();
		this.pSimpleExpression = new SimpleExpressionElements();
		this.pReferenceExpression = new ReferenceExpressionElements();
		this.pElementExpression = new ElementExpressionElements();
		this.pVariableExpression = new VariableExpressionElements();
		this.pStringExpression = new StringExpressionElements();
		this.pIntegerExpression = new IntegerExpressionElements();
		this.pBooleanExpression = new BooleanExpressionElements();
	}
	
	protected Grammar internalFindGrammar(GrammarProvider grammarProvider) {
		Grammar grammar = grammarProvider.getGrammar(this);
		while (grammar != null) {
			if ("webtest.dsl.WebTestDsl".equals(grammar.getName())) {
				return grammar;
			}
			List<Grammar> grammars = grammar.getUsedGrammars();
			if (!grammars.isEmpty()) {
				grammar = grammars.iterator().next();
			} else {
				return null;
			}
		}
		return grammar;
	}
	
	@Override
	public Grammar getGrammar() {
		return grammar;
	}
	
	
	public TerminalsGrammarAccess getTerminalsGrammarAccess() {
		return gaTerminals;
	}

	
